@pushOnce('scripts')
<script type="text/x-template" id="dl-batch-template"><section class="text-gray-800 dark:text-gray-200" aria-live="polite"><h3 class="font-semibold">Selected image previews</h3><p v-if="state">@{{state.count}} images · @{{state.status}}</p><p v-if="error || state?.error" role="alert">@{{error || state.error}}</p><div v-for="child in state?.children || []" :key="child.id" class="mt-3"><v-dreamlayer-workflow :descriptor="{type:'dreamlayer.workflow',id:child.id}"></v-dreamlayer-workflow></div></section></script>
<script type="module">
app.component('v-dreamlayer-batch',{template:'#dl-batch-template',props:['descriptor'],data:()=>({state:null,error:null,timer:null,stopped:false}),mounted(){this.poll();document.addEventListener('visibilitychange',this.wake)},beforeUnmount(){this.stopped=true;clearTimeout(this.timer);document.removeEventListener('visibilitychange',this.wake)},methods:{wake(){clearTimeout(this.timer);this.poll()},async poll(){if(this.stopped||document.hidden)return;try{const r=await this.$axios.get(@json(url(config('app.admin_url').'/dreamlayer/batches'))+'/'+this.descriptor.id);this.state=r.data;this.error=null}catch(e){this.error='Could not load batch progress.';if([401,403,404].includes(e.response?.status))return}if(!this.stopped&&!['completed','partial','failed'].includes(this.state?.status))this.timer=setTimeout(()=>this.poll(),2000)}}});
</script>
@endPushOnce
